/**
 * OpenAPI spec generation script for CipherBox API.
 *
 * This script creates a minimal NestJS application context specifically
 * for generating the OpenAPI specification without requiring a live database.
 */
import 'reflect-metadata';
import { NestFactory } from '@nestjs/core';
import { SwaggerModule, DocumentBuilder } from '@nestjs/swagger';
import { Module } from '@nestjs/common';
import { ThrottlerModule } from '@nestjs/throttler';
import { writeFileSync, mkdirSync } from 'fs';
import { join } from 'path';

// Import controllers that define the API
import { AppController } from '../src/app.controller';
import { AppService } from '../src/app.service';
import { AuthController } from '../src/auth/auth.controller';
import { AuthService } from '../src/auth/auth.service';
import { AuthMethodService } from '../src/auth/services/auth-method.service';
import { TestAuthService } from '../src/auth/services/test-auth.service';
import { Web3AuthVerifierService } from '../src/auth/services/web3auth-verifier.service';
import { TokenService } from '../src/auth/services/token.service';
import { JwtIssuerService } from '../src/auth/services/jwt-issuer.service';
import { GoogleOAuthService } from '../src/auth/services/google-oauth.service';
import { EmailOtpService } from '../src/auth/services/email-otp.service';
import { SiweService } from '../src/auth/services/siwe.service';
import { IdentityController } from '../src/auth/controllers/identity.controller';
import { IpfsController } from '../src/ipfs/ipfs.controller';
import { IPFS_PROVIDER } from '../src/ipfs/providers';
import { VaultController } from '../src/vault/vault.controller';
import { VaultService } from '../src/vault/vault.service';
import { IpnsController } from '../src/ipns/ipns.controller';
import { IpnsService } from '../src/ipns/ipns.service';
import { DeviceApprovalController } from '../src/device-approval/device-approval.controller';
import { DeviceApprovalService } from '../src/device-approval/device-approval.service';
import { SharesController } from '../src/shares/shares.controller';
import { InvitesController } from '../src/shares/invites.controller';
import { ShareInvitesController } from '../src/shares/share-invites.controller';
import { SharesService } from '../src/shares/shares.service';
import { ShareInviteService } from '../src/shares/share-invite.service';
import { Share } from '../src/shares/entities/share.entity';
import { ShareKey } from '../src/shares/entities/share-key.entity';
import { ShareInvite } from '../src/shares/entities/share-invite.entity';
import { MetricsService } from '../src/metrics/metrics.service';
import { TeeController } from '../src/tee/tee.controller';
import { TeeService } from '../src/tee/tee.service';
import { User } from '../src/auth/entities/user.entity';
import { AuthMethod } from '../src/auth/entities/auth-method.entity';
import { RefreshToken } from '../src/auth/entities/refresh-token.entity';
import { getRepositoryToken } from '@nestjs/typeorm';
import { ConfigService } from '@nestjs/config';
import { REDIS_CLIENT } from '../src/common/redis.module';

// Mock providers for OpenAPI generation - these won't be called
const mockRepository = {
  provide: getRepositoryToken(User),
  useValue: {},
};

const mockAuthMethodRepository = {
  provide: getRepositoryToken(AuthMethod),
  useValue: {},
};

const mockRefreshTokenRepository = {
  provide: getRepositoryToken(RefreshToken),
  useValue: {},
};

const mockShareRepository = {
  provide: getRepositoryToken(Share),
  useValue: {},
};

const mockShareKeyRepository = {
  provide: getRepositoryToken(ShareKey),
  useValue: {},
};

const mockShareInviteRepository = {
  provide: getRepositoryToken(ShareInvite),
  useValue: {},
};

const mockJwtService = {
  provide: 'JwtService',
  useValue: { sign: () => '' },
};

const mockConfigService = {
  provide: ConfigService,
  useValue: { get: () => 'mock-value' },
};

// Minimal module for OpenAPI generation - no database connection needed
@Module({
  imports: [
    // ThrottlerModule is required because IpnsController uses ThrottlerGuard
    ThrottlerModule.forRoot([{ ttl: 60000, limit: 10 }]),
  ],
  controllers: [
    AppController,
    AuthController,
    IdentityController,
    IpfsController,
    VaultController,
    IpnsController,
    DeviceApprovalController,
    SharesController,
    InvitesController,
    ShareInvitesController,
    TeeController,
  ],
  providers: [
    AppService,
    {
      provide: AuthService,
      useValue: {},
    },
    {
      provide: AuthMethodService,
      useValue: {},
    },
    {
      provide: TestAuthService,
      useValue: {},
    },
    {
      provide: Web3AuthVerifierService,
      useValue: {},
    },
    {
      provide: TokenService,
      useValue: {},
    },
    {
      provide: JwtIssuerService,
      useValue: { getJwksData: () => ({ keys: [] }) },
    },
    {
      provide: GoogleOAuthService,
      useValue: {},
    },
    {
      provide: EmailOtpService,
      useValue: {},
    },
    {
      provide: SiweService,
      useValue: {},
    },
    {
      provide: IPFS_PROVIDER,
      useValue: {},
    },
    {
      provide: VaultService,
      useValue: {},
    },
    {
      provide: IpnsService,
      useValue: {},
    },
    {
      provide: DeviceApprovalService,
      useValue: {},
    },
    {
      provide: SharesService,
      useValue: {},
    },
    {
      provide: ShareInviteService,
      useValue: {},
    },
    {
      provide: MetricsService,
      useValue: {},
    },
    {
      provide: TeeService,
      useValue: {},
    },
    mockRepository,
    mockAuthMethodRepository,
    mockRefreshTokenRepository,
    mockShareRepository,
    mockShareKeyRepository,
    mockShareInviteRepository,
    mockJwtService,
    mockConfigService,
    {
      provide: REDIS_CLIENT,
      useValue: {},
    },
  ],
})
class OpenApiGeneratorModule {}

async function generateOpenApiSpec() {
  const openApiVersion = process.env.npm_package_version;
  if (!openApiVersion) {
    throw new Error(
      'npm_package_version is required. Run via pnpm script: pnpm --filter @cipherbox/api openapi:generate'
    );
  }

  // Create app without starting HTTP server
  const app = await NestFactory.create(OpenApiGeneratorModule, {
    logger: false,
  });

  const config = new DocumentBuilder()
    .setTitle('CipherBox API')
    .setDescription('Zero-knowledge encrypted cloud storage API')
    .setVersion(openApiVersion)
    .addBearerAuth()
    .addTag('Health', 'Health check endpoints')
    .addTag('Root', 'API root endpoints')
    .addTag('Auth', 'Authentication endpoints')
    .addTag('Identity', 'CipherBox identity provider endpoints')
    .addTag('Vault', 'Vault management endpoints')
    .addTag('Files', 'File operations endpoints')
    .addTag('IPFS', 'IPFS relay endpoints')
    .addTag('IPNS', 'IPNS relay endpoints')
    .addTag('device-approval', 'Cross-device approval endpoints')
    .addTag('shares', 'User-to-user sharing endpoints')
    .addTag('invites', 'Public invite link endpoints')
    .addTag('share-invites', 'Authenticated invite management endpoints')
    .addTag('tee', 'TEE worker proxy endpoints')
    .build();

  // Create document from the app
  const document = SwaggerModule.createDocument(app, config);

  // Manually add health endpoint to spec (since we can't inject the real controller
  // without TypeORM dependencies)
  document.paths['/health'] = {
    get: {
      operationId: 'HealthController_check',
      summary: 'Check API and database health',
      tags: ['Health'],
      responses: {
        '200': {
          description: 'Health check passed',
          content: {
            'application/json': {
              schema: {
                type: 'object',
                required: ['status', 'details', 'version'],
                properties: {
                  status: { type: 'string', example: 'ok' },
                  info: {
                    type: 'object',
                    properties: {
                      database: {
                        type: 'object',
                        properties: {
                          status: { type: 'string', example: 'up' },
                        },
                      },
                    },
                  },
                  error: {
                    type: 'object',
                    additionalProperties: true,
                  },
                  details: {
                    type: 'object',
                    properties: {
                      database: {
                        type: 'object',
                        properties: {
                          status: { type: 'string', example: 'up' },
                        },
                      },
                    },
                  },
                  version: { type: 'string', example: openApiVersion },
                },
              },
            },
          },
        },
        '503': {
          description: 'Health check failed',
        },
      },
    },
  };

  // Ensure output directory exists
  const outputDir = join(__dirname, '..', '..', '..', 'packages', 'api-client');
  mkdirSync(outputDir, { recursive: true });

  const outputPath = join(outputDir, 'openapi.json');
  writeFileSync(outputPath, JSON.stringify(document, null, 2));

  console.log(`OpenAPI spec written to: ${outputPath}`);

  await app.close();
  process.exit(0);
}

generateOpenApiSpec().catch((error) => {
  console.error('Failed to generate OpenAPI spec:', error);
  process.exit(1);
});

