const {execSync} = require('child_process');
const fs = require('fs');
const committed = JSON.parse(execSync('git show HEAD:packages/api-client/openapi.json', {encoding:'utf8'}));
const generated = JSON.parse(fs.readFileSync('packages/api-client/openapi.json', 'utf8'));
// Find differences
function diff(a, b, path='') {
  if (typeof a !== typeof b) { console.log(path, 'type diff:', typeof a, typeof b); return; }
  if (typeof a !== 'object' || a === null) {
    if (a !== b) console.log(path, JSON.stringify(a), '->', JSON.stringify(b));
    return;
  }
  const keys = new Set([...Object.keys(a), ...Object.keys(b)]);
  for (const k of keys) diff(a[k], b[k], path+'.'+k);
}
diff(committed, generated);
"

